"use client";

import {
  closestCenter,
  DndContext,
  type DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { v4 as uuidv4 } from "uuid";

import {
  type CallFlow,
  type CallFlowTask,
  createDefaultGreetingConfig,
  createDefaultOutroConfig,
  type GreetingConfig,
  type OutroConfig,
} from "@/common/models/interview-builder";
import { useTRPC } from "@/trpc/client";

import { useInterviewBuilder } from "../hooks/use-interview-builder";
import { SortableTaskCard } from "./sortable-task-card";
import { GreetingTaskCard } from "./task-cards/greeting-task-card";
import { OutroTaskCard } from "./task-cards/outro-task-card";
import { TaskTypeSelector } from "./task-type-selector";

interface JsonSchema {
  title?: string;
  type?: string;
  properties?: Record<string, unknown>;
  required?: string[];
}

interface CallFlowStepProps {
  jobId: string;
  organizationId: string;
  onDirtyChange?: (isDirty: boolean) => void;
  registerSaveHandler?: (handler: () => Promise<void> | void) => void;
  onStepValidation?: (validation: { canProceed: boolean }) => void;
}

export function CallFlowStep({
  jobId,
  organizationId,
  onDirtyChange,
  registerSaveHandler,
  onStepValidation,
}: CallFlowStepProps) {
  const { interviewBuilder, jobData, isLoading, updateLocalState } =
    useInterviewBuilder({
      jobId,
      organizationId,
    });

  const [callFlow, setCallFlow] = useState<CallFlow>({
    tasks: [],
    isComplete: false,
  });

  const [greetingConfig, setGreetingConfig] = useState<GreetingConfig | null>(
    null,
  );
  const [isGreetingActive, setIsGreetingActive] = useState(false);
  const [outroConfig, setOutroConfig] = useState<OutroConfig | null>(null);
  const [isOutroActive, setIsOutroActive] = useState(false);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);
  const [taskValidationErrors, setTaskValidationErrors] = useState<
    Record<string, boolean>
  >({});

  const trpc = useTRPC();

  // Fetch candidate data point schemas
  const { data: schemas } = useQuery(
    trpc.candidateDataPointSchema.list.queryOptions({
      activeOnly: true,
    }),
  );

  // Get available data points from schemas
  const availableDataPoints = schemas
    ? schemas.map((schema) => {
        const jsonSchema = schema.jsonSchema as JsonSchema;
        return {
          key: schema.schemaKey,
          label: jsonSchema.title ?? schema.schemaKey,
        };
      })
    : [];

  const { mutateAsync: updateCallFlow } = useMutation(
    trpc.interviewBuilder.updateCallFlow.mutationOptions({
      onSuccess: () => {
        toast.success("Call flow saved");
        onDirtyChange?.(false);
      },
      onError: (error) => {
        const message =
          error instanceof Error ? error.message : "Failed to save call flow";
        toast.error(`Failed to save call flow: ${message}`);
      },
    }),
  );

  const { mutateAsync: updateGreetingConfigMutation } = useMutation(
    trpc.interviewBuilder.updateGreetingConfig.mutationOptions({
      onSuccess: () => {
        toast.success("Greeting configuration saved");
        onDirtyChange?.(false);
      },
      onError: (error) => {
        const message =
          error instanceof Error
            ? error.message
            : "Failed to save greeting configuration";
        toast.error(`Failed to save greeting configuration: ${message}`);
      },
    }),
  );

  const { mutateAsync: updateOutroConfigMutation } = useMutation(
    trpc.interviewBuilder.updateOutroConfig.mutationOptions({
      onSuccess: () => {
        toast.success("Outro configuration saved");
        onDirtyChange?.(false);
      },
      onError: (error) => {
        const message =
          error instanceof Error
            ? error.message
            : "Failed to save outro configuration";
        toast.error(`Failed to save outro configuration: ${message}`);
      },
    }),
  );

  // Initialize local state from interview builder - only on initial load
  useEffect(() => {
    if (interviewBuilder?.callFlow) {
      setCallFlow(interviewBuilder.callFlow);
    }
  }, [interviewBuilder?.callFlow]);

  // Initialize greeting config only once when data becomes available
  useEffect(() => {
    // Only set if we don't have a greeting config yet
    if (greetingConfig === null) {
      if (interviewBuilder?.greetingConfig) {
        setGreetingConfig(interviewBuilder.greetingConfig);
      } else if (jobData?.title) {
        setGreetingConfig(createDefaultGreetingConfig(jobData.title));
      }
    }
  }, [interviewBuilder?.greetingConfig, jobData?.title, greetingConfig]);

  // Initialize outro config only once when data becomes available
  useEffect(() => {
    // Only set if we don't have an outro config yet
    if (outroConfig === null) {
      if (interviewBuilder?.outroConfig) {
        setOutroConfig(interviewBuilder.outroConfig);
      } else if (jobData?.title) {
        setOutroConfig(createDefaultOutroConfig(jobData.title));
      }
    }
  }, [interviewBuilder?.outroConfig, jobData?.title, outroConfig]);

  // Update parent validation state
  useEffect(() => {
    // Check all tasks for validation errors
    const errors: Record<string, boolean> = {};
    callFlow.tasks.forEach((task) => {
      errors[task.id] = checkTaskValidationErrors(task);
    });
    setTaskValidationErrors(errors);

    // Validate that we have at least one task and no validation errors
    const hasAtLeastOneTask = callFlow.tasks.length > 0;
    const hasValidationErrors = Object.values(errors).some(
      (hasError) => hasError,
    );

    onStepValidation?.({
      canProceed: hasAtLeastOneTask && !hasValidationErrors,
    });
  }, [callFlow.tasks, onStepValidation, checkTaskValidationErrors]);

  // Register save handler with parent
  useEffect(() => {
    const saveHandler = async () => {
      const hasAtLeastOneTask = callFlow.tasks.length > 0;

      if (!hasAtLeastOneTask) {
        toast.error("Please add at least one task before saving");
        return;
      }

      // Save greeting, outro, and call flow
      if (greetingConfig) {
        await updateGreetingConfigMutation({
          organizationId,
          jobId,
          greetingConfig,
        });
      }

      if (outroConfig) {
        await updateOutroConfigMutation({
          organizationId,
          jobId,
          outroConfig,
        });
      }

      await updateCallFlow({
        organizationId,
        jobId,
        data: {
          ...callFlow,
          isComplete: true,
        },
      });

      // Update local state
      if (interviewBuilder) {
        updateLocalState({
          ...interviewBuilder,
          greetingConfig: greetingConfig || undefined,
          outroConfig: outroConfig || undefined,
          callFlow: {
            ...callFlow,
            isComplete: true,
          },
          completedSteps: [...new Set([...interviewBuilder.completedSteps, 3])],
        });
      }
    };

    registerSaveHandler?.(saveHandler);
  }, [
    callFlow,
    greetingConfig,
    outroConfig,
    updateCallFlow,
    updateGreetingConfigMutation,
    updateOutroConfigMutation,
    organizationId,
    jobId,
    registerSaveHandler,
    updateLocalState,
    interviewBuilder,
  ]);

  // Drag and drop sensors
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (active.id !== over?.id) {
      const oldIndex = callFlow.tasks.findIndex((t) => t.id === active.id);
      const newIndex = callFlow.tasks.findIndex((t) => t.id === over?.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        const newTasks = arrayMove(callFlow.tasks, oldIndex, newIndex);

        setCallFlow((prev) => ({
          ...prev,
          tasks: newTasks,
        }));

        onDirtyChange?.(true);
      }
    }
  };

  const handleAddDataCollectionTask = (dataPointKey: string) => {
    const schema = schemas?.find((s) => s.schemaKey === dataPointKey);
    const jsonSchema = schema?.jsonSchema as JsonSchema | undefined;

    const newTask: CallFlowTask = {
      id: uuidv4(),
      title: jsonSchema?.title ?? dataPointKey,
      taskType: "DATA_COLLECTION",
      initialMessage: schema?.defaultPrompt ?? "",
      instructions: "",
      candidateDataPointToCollect: dataPointKey,
      requirementId: undefined,
      validations: [],
      enabled: true,
    };

    setCallFlow((prev) => ({
      ...prev,
      tasks: [...prev.tasks, newTask],
    }));

    setActiveTaskId(newTask.id);
    onDirtyChange?.(true);
  };

  const handleAddConfirmationTask = () => {
    const newTask: CallFlowTask = {
      id: uuidv4(),
      title: "Confirmation Question",
      taskType: "CONFIRMATION",
      initialMessage: "",
      instructions: "",
      validations: [],
      enabled: true,
    };

    setCallFlow((prev) => ({
      ...prev,
      tasks: [...prev.tasks, newTask],
    }));
    setActiveTaskId(newTask.id);
    onDirtyChange?.(true);
  };

  const handleAddQATask = () => {
    const newTask: CallFlowTask = {
      id: uuidv4(),
      title: "Q&A Session",
      taskType: "QA",
      initialMessage:
        "Do you have any questions about the role or our company?",
      instructions:
        "Answer the candidate's questions clearly and concisely. Provide helpful information about the role, company culture, and expectations.",
      validations: [],
      enabled: true,
    };

    setCallFlow((prev) => ({
      ...prev,
      tasks: [...prev.tasks, newTask],
    }));
    setActiveTaskId(newTask.id);
    onDirtyChange?.(true);
  };

  const handleAddBehavioralTask = () => {
    const newTask: CallFlowTask = {
      id: uuidv4(),
      title: "Behavioral Question",
      taskType: "BEHAVIORAL",
      initialMessage: "",
      instructions: "",
      validations: [],
      enabled: true,
    };

    setCallFlow((prev) => ({
      ...prev,
      tasks: [...prev.tasks, newTask],
    }));
    setActiveTaskId(newTask.id);
    onDirtyChange?.(true);
  };

  const checkTaskValidationErrors = useCallback(
    (task: CallFlowTask): boolean => {
      // Check if any enabled validation has no value set
      return task.validations.some(
        (validation) =>
          validation.enabled &&
          validation.operator !== "hasValue" && // Skip value check for hasValue operator
          (validation.value === "" ||
            (Array.isArray(validation.value) && validation.value.length === 0)),
      );
    },
    [],
  );
  const handleUpdateTask = (task: CallFlowTask) => {
    setCallFlow((prev) => ({
      ...prev,
      tasks: prev.tasks.map((t) => (t.id === task.id ? task : t)),
    }));

    // Check and update validation errors for this task
    const hasErrors = checkTaskValidationErrors(task);
    setTaskValidationErrors((prev) => ({
      ...prev,
      [task.id]: hasErrors,
    }));

    onDirtyChange?.(true);
  };

  const handleToggleActive = (taskId: string) => {
    // When toggling a regular task, close greeting/outro if open
    if (isGreetingActive) {
      setIsGreetingActive(false);
    }
    if (isOutroActive) {
      setIsOutroActive(false);
    }
    setActiveTaskId(activeTaskId === taskId ? null : taskId);
  };

  const handleToggleGreeting = () => {
    // When toggling greeting, close any open task or outro
    if (activeTaskId) {
      setActiveTaskId(null);
    }
    if (isOutroActive) {
      setIsOutroActive(false);
    }
    setIsGreetingActive((prev) => !prev);
    // Don't mark as dirty just for toggling the view
  };

  const handleToggleOutro = () => {
    // When toggling outro, close any open task or greeting
    if (activeTaskId) {
      setActiveTaskId(null);
    }
    if (isGreetingActive) {
      setIsGreetingActive(false);
    }
    setIsOutroActive((prev) => !prev);
    // Don't mark as dirty just for toggling the view
  };

  const handleUpdateGreeting = (config: GreetingConfig) => {
    setGreetingConfig(config);
    onDirtyChange?.(true);
  };

  const handleUpdateOutro = (config: OutroConfig) => {
    setOutroConfig(config);
    onDirtyChange?.(true);
  };

  const handleDeleteTask = (taskId: string) => {
    setCallFlow((prev) => ({
      ...prev,
      tasks: prev.tasks.filter((t) => t.id !== taskId),
    }));

    if (activeTaskId === taskId) {
      setActiveTaskId(null);
    }

    onDirtyChange?.(true);
  };

  // Get available requirements (exclude ones already used in tasks)
  const usedRequirementIds = callFlow.tasks
    .filter((t) => t.taskType === "REQUIREMENT" && Boolean(t.requirementId))
    .map((t) => t.requirementId)
    .filter((id): id is string => id !== undefined);

  const availableRequirements = (interviewBuilder?.scorecard.requirements || [])
    .filter((req) => !usedRequirementIds.includes(req.id))
    .map((req) => ({
      id: req.id,
      name: req.name,
    }));

  if (isLoading) {
    return (
      <div className="flex justify-center py-8">
        <div className="text-center">
          <div className="mx-auto h-8 w-8 animate-spin rounded-full border-b-2 border-purple-600"></div>
          <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
            Loading call flow...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100">
            Call Flow
          </h2>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Configure the tasks that will be executed during the interview.
          </p>
        </div>
      </div>

      {/* Greeting Card - Always First */}
      {greetingConfig && (
        <div className="mb-2">
          <GreetingTaskCard
            greetingConfig={greetingConfig}
            isActive={isGreetingActive}
            fallbackLanguage={jobData?.callLanguage || "en"}
            onToggleActive={handleToggleGreeting}
            onUpdate={handleUpdateGreeting}
          />
        </div>
      )}

      <div className="space-y-2">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={callFlow.tasks.map((t) => t.id)}
            strategy={verticalListSortingStrategy}
          >
            {callFlow.tasks.map((task, index) => {
              // Include the current task's requirement in available list
              const taskAvailableRequirements = [
                ...availableRequirements,
                ...(task.requirementId &&
                interviewBuilder?.scorecard.requirements
                  ? interviewBuilder.scorecard.requirements
                      .filter((req) => req.id === task.requirementId)
                      .map((req) => ({
                        id: req.id,
                        name: req.name,
                      }))
                  : []),
              ];

              return (
                <SortableTaskCard
                  key={task.id}
                  task={task}
                  index={index + 1}
                  isActive={activeTaskId === task.id}
                  availableDataPoints={availableDataPoints}
                  availableRequirements={taskAvailableRequirements}
                  schemas={schemas?.map((s) => ({
                    schemaKey: s.schemaKey,
                    defaultPrompt: s.defaultPrompt,
                    jsonSchema: s.jsonSchema as JsonSchema | undefined,
                  }))}
                  allRequirements={interviewBuilder?.scorecard.requirements}
                  fallbackLanguage={jobData?.callLanguage || "en"}
                  onToggleActive={() => handleToggleActive(task.id)}
                  onUpdate={handleUpdateTask}
                  onDelete={() => handleDeleteTask(task.id)}
                  hasValidationErrors={taskValidationErrors[task.id] || false}
                />
              );
            })}
          </SortableContext>
        </DndContext>

        <TaskTypeSelector
          onAddDataCollection={handleAddDataCollectionTask}
          onAddConfirmation={handleAddConfirmationTask}
          onAddQA={handleAddQATask}
          onAddBehavioral={handleAddBehavioralTask}
          dataPointSchemas={schemas?.map((s) => ({
            schemaKey: s.schemaKey,
            schemaVersion: null,
            jsonSchema: s.jsonSchema as {
              title?: string;
              type?: string;
              description?: string;
              properties?: Record<
                string,
                {
                  title?: string;
                  type?: string;
                  description?: string;
                  format?: string;
                }
              >;
            },
          }))}
          className="pt-4"
        />
      </div>

      {/* Outro Card - Always Last */}
      {outroConfig && (
        <div className="mt-2">
          <OutroTaskCard
            outroConfig={outroConfig}
            isActive={isOutroActive}
            fallbackLanguage={jobData?.callLanguage || "en"}
            onToggleActive={handleToggleOutro}
            onUpdate={handleUpdateOutro}
          />
        </div>
      )}
    </div>
  );
}

