import { type Prisma } from "@purplefish-ai/db";

import type { JobSource } from "@/common/models/jobs";
import { sendSlackMessage } from "@/server/libs/slack";
import {
  getIntegrationCursors,
  upsertIntegrationCursor,
} from "@/server/resource_access/ats-integration-cursor-resource-accessor";
import { findJobByAtsId } from "@/server/resource_access/job-resource-accessor";
import {
  type JobSyncData,
  JobSyncer,
} from "@/server/services/integrations/syncers/job-syncer";

import type {
  SyncCandidatesParams,
  SyncJobsParams,
  SyncResult,
} from "../../abstractions/base";
import type { SyncProvider } from "../../abstractions/sync";
import { KomboApiClient } from "../client";
import type { KomboCandidate, KomboJob } from "../client/types";
import type { ATSSystemConfig, KomboConfig, KomboToken } from "../config/types";
import { getJobSourceForKomboSystem, INTERNAL_JOB_STATUS } from "../constants";
import { MapperFactory } from "../mappers/factory";
import { syncApplications } from "../sync/applications";

// All job sync fields are inherited from base SyncJobsParams:
// - since: for incremental sync timestamp
// - shouldCreateNewJobs: to control job creation
// - isFullSync: to indicate full sync vs incremental

export class KomboSyncProvider
  implements SyncProvider<KomboConfig, KomboToken>
{
  constructor(
    private atsSystem: string,
    private systemConfig: ATSSystemConfig,
  ) {}

  /**
   * Fetch and store ATS application stages
   * Should be called when setting up or refreshing an integration
   */
  async fetchAndStoreStages(
    config: KomboConfig,
    token: KomboToken,
    integrationId: string,
  ): Promise<void> {
    const client = new KomboApiClient(token.apiKey, config.komboIntegrationId);
    const mapper = MapperFactory.getMapper(
      this.systemConfig.fieldMapper || "default",
    );

    try {
      console.log(
        `[KomboSync] Fetching application stages for integration ${integrationId}`,
      );

      // Fetch all stages from Kombo
      const stages = await client.fetchApplicationStages();

      console.log(`[KomboSync] Fetched ${stages.length} stages from Kombo`);

      // Transform to storage format
      const stagesMap: Record<
        string,
        {
          id: string;
          remote_id: string;
          name: string;
        }
      > = {};

      for (const stage of stages) {
        // Use mapper-specific normalization if available
        let stageName: string;
        const hasNormalizer =
          "normalizeStageNameForKey" in mapper &&
          typeof mapper.normalizeStageNameForKey === "function";
        if (hasNormalizer) {
          stageName = mapper.normalizeStageNameForKey!(stage.name);
        } else {
          // Default normalization
          stageName = stage.name
            .toUpperCase()
            .replace(/\s+/g, "_")
            .replace(/[^A-Z0-9_]/g, "");
        }

        stagesMap[stageName] = {
          id: stage.id,
          remote_id: stage.remote_id,
          name: stage.name,
        };

        console.log(
          `[KomboSync] Mapped stage: ${stageName} -> ${stage.name} (ID: ${stage.id})`,
        );
      }

      // Get default stage transitions using mapper if available
      let stageTransitions: Record<string, string | undefined> = {};

      const hasTransitions =
        "getDefaultStageTransitions" in mapper &&
        typeof mapper.getDefaultStageTransitions === "function";
      if (hasTransitions) {
        stageTransitions = mapper.getDefaultStageTransitions!(stagesMap);
      } else {
        // Fallback to generic logic
        // Look for interview-related stages for completed status
        const interviewStage = Object.entries(stagesMap).find(
          ([key]) =>
            key.includes("INTERVIEW") ||
            key.includes("SCREEN") ||
            key.includes("PHONE"),
        );
        if (interviewStage) {
          // Use the actual stage ID, not the remote_id (key)
          const stageData = interviewStage[1] as {
            id: string;
          };
          stageTransitions.completed = stageData.id;
        }

        // Look for withdrawn/rejected stages for candidate_declined
        const withdrawnStage = Object.entries(stagesMap).find(
          ([key]) =>
            key.includes("WITHDRAWN") ||
            key.includes("DECLINED") ||
            key.includes("REJECTED"),
        );
        if (withdrawnStage) {
          // Use the actual stage ID, not the remote_id (key)
          const stageData = withdrawnStage[1] as {
            id: string;
          };
          stageTransitions.candidate_declined = stageData.id;
        }

        // sequence_ended typically doesn't have a stage transition
        // stageTransitions.sequence_ended = undefined;
      }

      console.log("[KomboSync] Default stage transitions:", stageTransitions);

      // Update the integration config with stages
      const { db } = await import("@purplefish-ai/db/server");

      const existingIntegration = await db.atsIntegration.findUnique({
        where: {
          id: integrationId,
        },
        select: {
          config: true,
        },
      });

      if (!existingIntegration) {
        throw new Error(`Integration ${integrationId} not found`);
      }

      // Merge with existing config
      const existingConfig = existingIntegration.config as Record<
        string,
        unknown
      >;
      const existingTransitions = existingConfig.stageTransitions as
        | Record<string, string | undefined>
        | undefined;

      // Only apply default transitions if no transitions are configured at all
      // If user has explicitly configured transitions (even if empty), respect that
      const hasUserConfiguration = Object.hasOwn(
        existingConfig,
        "stageTransitions",
      );
      const finalTransitions = hasUserConfiguration
        ? existingTransitions // Keep user's configuration (could be undefined or empty object)
        : stageTransitions; // Apply defaults only on first sync

      const updatedConfig = {
        ...existingConfig,
        stages: stagesMap,
        // Always preserve stageTransitions if user has configured it (even if empty)
        ...(hasUserConfiguration ||
        (finalTransitions && Object.keys(finalTransitions).length > 0)
          ? {
              stageTransitions: finalTransitions || {},
            }
          : {}),
      };

      await db.atsIntegration.update({
        where: {
          id: integrationId,
        },
        data: {
          config: updatedConfig as unknown as Prisma.JsonValue,
        },
      });

      console.log(
        "[KomboSync] Successfully stored " +
          Object.keys(stagesMap).length +
          " stages for integration " +
          integrationId,
      );
    } catch (error) {
      console.error("[KomboSync] Failed to fetch and store stages:", error);
      throw error;
    }
  }

  async syncCandidates?(
    config: KomboConfig,
    token: KomboToken,
    params: SyncCandidatesParams,
  ): Promise<SyncResult> {
    // This method is deprecated in favor of syncApplications
    // Keeping for backward compatibility
    return this.syncApplications(config, token, params);
  }

  /**
   * Sync applications (candidates + opportunities) from Kombo
   * This handles both candidate creation/update and opportunity management
   *
   * Delegates to the refactored implementation in sync/applications
   */
  async syncApplications(
    config: KomboConfig,
    token: KomboToken,
    params: SyncCandidatesParams,
  ): Promise<SyncResult> {
    // Use the refactored syncApplications function
    return syncApplications(config, token, params);
  }

  async syncJobs?(
    config: KomboConfig,
    token: KomboToken,
    params: SyncJobsParams,
  ): Promise<SyncResult> {
    const client = new KomboApiClient(
      token.apiKey,
      config.komboIntegrationId,
      params.organizationId,
    );
    const mapper = MapperFactory.getMapper(
      this.systemConfig.fieldMapper || "default",
    );

    // Determine if this is a full sync (no updated_after filter)
    const isFullSync = params.isFullSync ?? !params.since;

    console.log(
      `[KomboSync] Job sync - (since: ${params.since?.toISOString() ?? "N/A"}, isFullSync: ${isFullSync})`,
    );

    try {
      // Fetch ALL jobs using pagination
      const allJobs: KomboJob[] = [];
      let cursor: string | null = params.cursor || null;
      let pageCount = 0;
      const pageSize = params.limit ?? 50;

      console.log(
        `[KomboSync] Starting paginated fetch of jobs (page size: ${pageSize})`,
      );

      while (true) {
        pageCount++;

        // Build request params for this page
        const jobsRequest: Parameters<typeof client.getJobs>[0] = {
          updated_after: params.since?.toISOString(),
          cursor: cursor || undefined,
          page_size: pageSize,
        };

        const response = await client.getJobs(jobsRequest);

        if (response.status !== "success") {
          throw new Error(response.error?.message ?? "Failed to fetch jobs");
        }

        console.log(
          `[KomboSync] Page ${pageCount}: Received ${response.data.results.length} jobs`,
        );

        // Add results to our collection
        allJobs.push(...response.data.results);

        // Check if there are more pages
        if (response.data.next) {
          cursor = response.data.next;
          console.log(
            "[KomboSync] More pages available, fetching next page...",
          );
        } else {
          console.log("[KomboSync] No more pages, finished fetching jobs");
          break;
        }

        // Safety check to prevent infinite loops (max 50 pages = 2,500 jobs)
        if (pageCount >= 50) {
          console.warn(
            "[KomboSync] Reached maximum page limit (50), stopping pagination",
          );
          break;
        }
      }

      console.log(
        `[KomboSync] Total jobs fetched: ${allJobs.length} across ${pageCount} page(s)`,
      );

      // Check if we should create new jobs or only sync existing ones
      const shouldCreateNewJobs = params.shouldCreateNewJobs ?? true;
      const jobSyncData: JobSyncData[] = [];
      const unknownJobs: {
        atsId: string;
        title: string;
      }[] = [];
      const seenJobAtsIds = new Set<string>();

      // Process each job from Kombo
      for (const komboJob of allJobs) {
        const mappedJob = mapper.mapKomboJob(komboJob);

        // Track ALL ATS IDs we've seen
        seenJobAtsIds.add(mappedJob.atsId);

        // For closed/inactive jobs, we still want to update their status in our DB
        // but we log it for visibility
        if (mappedJob.status !== INTERNAL_JOB_STATUS.ACTIVE) {
          console.log(
            `[KomboSync] Found closed/inactive job from ATS: ${mappedJob.title} (ATS ID: ${mappedJob.atsId}, status: ${mappedJob.status})`,
          );
          // Continue processing to update the job's status in our database
        }

        // If we shouldn't create new jobs, check if this job exists
        if (!shouldCreateNewJobs) {
          const existingJob = await findJobByAtsId(
            params.organizationId,
            mappedJob.atsId,
          );

          if (!existingJob) {
            // Track unknown job for notification
            unknownJobs.push({
              atsId: mappedJob.atsId,
              title: mappedJob.title,
            });
            continue; // Skip this job
          }
        }

        // Add to sync data (all jobs including closed ones to update their status)
        jobSyncData.push({
          atsId: mappedJob.atsId,
          komboId: mappedJob.komboId, // Pass Kombo's internal ID
          title: mappedJob.title,
          description: mappedJob.description,
          status: mappedJob.status,
          location: mappedJob.location,
          additionalDatapoints: mappedJob.customFields,
          shouldSync: true, // Always sync jobs regardless of status
        });
      }

      // Send Slack notifications for unknown jobs (if any)
      const notificationMapper = MapperFactory.getMapper(this.atsSystem);
      const shouldNotify =
        "shouldNotifyUnknownJobs" in notificationMapper &&
        typeof notificationMapper.shouldNotifyUnknownJobs === "function";
      if (
        unknownJobs.length > 0 &&
        shouldNotify &&
        notificationMapper.shouldNotifyUnknownJobs!() === true
      ) {
        await this.notifyUnknownJobs(
          params.organizationId,
          params.integrationId,
          unknownJobs,
        );
      }

      // Use JobSyncer to handle the sync
      const jobSyncer = new JobSyncer({
        organizationId: params.organizationId,
        source: this.getJobSource(),
        allowCallTransfers: true,
        sendNotifications: true,
      });

      const syncResult = await jobSyncer.syncJobs(jobSyncData);

      console.log(
        `[KomboSync] Job sync complete. Synced ${jobSyncData.length} jobs. Total ATS jobs seen: ${seenJobAtsIds.size}`,
      );

      // Handle soft-deletes ONLY for full sync (when we have all jobs from ATS)
      let softDeletedJobs = 0;

      if (isFullSync) {
        console.log(
          "[KomboSync] Running soft-delete logic for jobs (full sync mode)",
        );

        // Get all existing jobs for this source
        const existingJobs = await this.getExistingJobsForSource(
          params.organizationId,
          this.getJobSource(),
        );

        console.log(
          `[KomboSync] Found ${existingJobs.length} existing jobs in DB, seen ${seenJobAtsIds.size} jobs from ATS`,
        );

        // Collect jobs to soft-delete (jobs that exist in DB but not in ATS response)
        const jobsToSoftDelete = existingJobs.filter(
          (existingJob) =>
            existingJob.atsId !== null && !seenJobAtsIds.has(existingJob.atsId),
        );

        if (jobsToSoftDelete.length > 0) {
          console.log(
            `[KomboSync] Jobs to soft-delete: ${jobsToSoftDelete.map((j) => `${j.title} (ATS ID: ${j.atsId})`).join(", ")}`,
          );
        }

        // Batch soft-delete jobs
        if (jobsToSoftDelete.length > 0) {
          await this.batchSoftDeleteJobs(jobsToSoftDelete);
          softDeletedJobs = jobsToSoftDelete.length;
        }

        if (softDeletedJobs > 0) {
          console.log(
            `[KomboSync] Soft-deleted ${softDeletedJobs} jobs that were removed from ATS`,
          );
        } else {
          console.log("[KomboSync] No jobs to soft-delete");
        }
      } else {
        console.log(
          "[KomboSync] Skipping soft-delete logic (incremental sync mode)",
        );
      }

      return {
        created: syncResult.created,
        updated: syncResult.updated,
        failed: syncResult.errors.length,
        skipped: unknownJobs.length, // Track skipped/unknown jobs
        errors: syncResult.errors.map((e) => ({
          externalId: e.atsId,
          error: e.error,
        })),
      };
    } catch (error) {
      console.error(`Kombo job sync error for ${this.atsSystem}:`, error);
      throw error;
    }
  }

  /**
   * Send Slack notifications for unknown jobs
   * Includes deduplication to avoid spam
   */
  private async notifyUnknownJobs(
    organizationId: string,
    integrationId: string,
    unknownJobs: {
      atsId: string;
      title: string;
    }[],
  ): Promise<void> {
    const NOTIFICATION_CURSOR_KEY = "unknown_jobs_notified";
    const NOTIFICATION_COOLDOWN_HOURS = 24; // Only notify once per day

    try {
      // Get existing cursor to check for deduplication
      const cursors = await getIntegrationCursors(integrationId);
      const notificationCursor = cursors.find(
        (c) => c.key === NOTIFICATION_CURSOR_KEY,
      );

      // Check if we've already notified recently
      if (
        notificationCursor?.cursor !== null &&
        notificationCursor?.cursor !== undefined
      ) {
        const lastNotified = new Date(notificationCursor.cursor as string);
        const hoursSinceLastNotification =
          (Date.now() - lastNotified.getTime()) / (1000 * 60 * 60);

        if (hoursSinceLastNotification < NOTIFICATION_COOLDOWN_HOURS) {
          console.log(
            `Skipping Slack notification - already notified ${hoursSinceLastNotification.toFixed(1)} hours ago`,
          );
          return;
        }
      }

      // Get previously notified job IDs to avoid duplicate notifications
      const NOTIFIED_JOBS_CURSOR_KEY = "notified_job_ids";
      const notifiedJobsCursor = cursors.find(
        (c) => c.key === NOTIFIED_JOBS_CURSOR_KEY,
      );
      const previouslyNotifiedIds =
        notifiedJobsCursor?.cursor !== null &&
        notifiedJobsCursor?.cursor !== undefined
          ? (notifiedJobsCursor.cursor as string[])
          : [];

      // Filter out jobs we've already notified about
      const newUnknownJobs = unknownJobs.filter(
        (job) => !previouslyNotifiedIds.includes(job.atsId),
      );

      if (newUnknownJobs.length === 0) {
        console.log("No new unknown jobs to notify about");
        return;
      }

      // Deduplicate by grouping multiple jobs into one message
      const jobCount = newUnknownJobs.length;
      const jobList = newUnknownJobs
        .slice(0, 5) // Limit to first 5 to avoid huge messages
        .map((job) => `• ${job.title} (ID: ${job.atsId})`);
      const moreJobsCount = jobCount > 5 ? jobCount - 5 : 0;

      // Get mapper to format the notification message
      const messageMapper = MapperFactory.getMapper(this.atsSystem);
      const hasFormatter =
        "formatUnknownJobsMessage" in messageMapper &&
        typeof messageMapper.formatUnknownJobsMessage === "function";
      const formattedMessage = hasFormatter
        ? messageMapper.formatUnknownJobsMessage!(
            jobCount,
            jobList,
            moreJobsCount,
          )
        : undefined;
      const message =
        formattedMessage ||
        `:information_source: Found ${jobCount} new job${jobCount === 1 ? "" : "s"} that ${jobCount === 1 ? "was" : "were"} not auto-imported.`;

      await sendSlackMessage(message, {
        orgId: organizationId,
      });

      // Update cursors to track notification
      await upsertIntegrationCursor(
        integrationId,
        NOTIFICATION_CURSOR_KEY,
        new Date().toISOString(),
      );

      // Update list of notified job IDs
      const allNotifiedIds = [
        ...previouslyNotifiedIds,
        ...newUnknownJobs.map((j) => j.atsId),
      ];
      await upsertIntegrationCursor(
        integrationId,
        NOTIFIED_JOBS_CURSOR_KEY,
        allNotifiedIds,
      );
    } catch (error) {
      console.error(
        "Failed to send Slack notification for unknown jobs:",
        error,
      );
    }
  }

  private getJobSource(): JobSource {
    // Map the ATS system to the appropriate JobSource using the centralized helper
    return getJobSourceForKomboSystem(this.atsSystem);
  }

  /**
   * Get existing jobs from this ATS source
   */
  private async getExistingJobsForSource(
    organizationId: string,
    source: string,
  ): Promise<
    {
      id: string;
      atsId: string | null;
      title: string;
    }[]
  > {
    const { db } = await import("@purplefish-ai/db/server");

    const jobs = await db.job.findMany({
      where: {
        organizationId,
        source,
        atsId: {
          not: null,
        },
        // Only get active jobs
        status: {
          not: INTERNAL_JOB_STATUS.CLOSED,
        },
      },
      select: {
        id: true,
        atsId: true,
        title: true,
      },
    });

    return jobs;
  }

  /**
   * Batch soft-delete jobs for better performance
   */
  private async batchSoftDeleteJobs(
    jobs: {
      id: string;
      atsId: string | null;
      title: string;
    }[],
  ): Promise<void> {
    const { db } = await import("@purplefish-ai/db/server");

    const jobIds = jobs.map((job) => job.id);

    // Batch update all jobs at once - only update jobs that aren't already closed
    const jobUpdateResult = await db.job.updateMany({
      where: {
        id: {
          in: jobIds,
        },
        status: {
          not: INTERNAL_JOB_STATUS.CLOSED,
        }, // Only update jobs that aren't already closed
      },
      data: {
        status: INTERNAL_JOB_STATUS.CLOSED,
      },
    });

    // Batch pause all opportunities for these jobs
    const oppUpdateResult = await db.opportunity.updateMany({
      where: {
        jobId: {
          in: jobIds,
        },
        paused: false,
      },
      data: {
        paused: true,
        pausedReason: "Job closed - removed from ATS during sync",
      },
    });

    if (jobUpdateResult.count > 0) {
      console.log(
        `[KomboSync] Successfully closed ${jobUpdateResult.count} jobs (out of ${jobs.length} attempted)`,
      );
    } else if (jobs.length > 0) {
      console.log(
        `[KomboSync] No jobs needed closing (all ${jobs.length} were already closed or don't exist)`,
      );
    }

    if (oppUpdateResult.count > 0) {
      console.log(
        `[KomboSync] Paused ${oppUpdateResult.count} opportunities for closed jobs`,
      );
    }

    // Log individual jobs for debugging if needed
    if (jobs.length < 10 && jobUpdateResult.count > 0) {
      jobs.forEach((job) => {
        console.log(
          `[KomboSync]   - Attempted to close: ${job.title} (ID: ${job.id}, ATS ID: ${job.atsId})`,
        );
      });
    }
  }
}

