import { db } from "@purplefish-ai/db/server";

import { populateVariablesInNotifications } from "@/common/libs/variables";
import { JobSource } from "@/common/models/jobs";
import { OPT_IN_TRIGGER } from "@/common/models/notification-templates";
import { TemplateVariableType } from "@/common/models/script-nodes";
import {
  type IInterviewPlan,
  optInStage,
  stages,
} from "@/common/models/stages";
import { createJobNotificationTemplateFromOrgNotificationTemplate } from "@/server/libs/notification-templates";

import { inngest } from "../client";

// Function to add opt-in stage to all jobs in organizations with SmartRecruiters integration
export const addOptInStageFunction = inngest.createFunction(
  {
    id: "add-opt-in-stage",
  },
  {
    event: "migrations/job.add_opt_in_stage.triggered" as const,
  },
  async ({ step }) => {
    // Find all organizations with SmartRecruiters integration
    const organizations = await step.run("get-organizations", async () => {
      const integrations = await db.atsIntegration.findMany({
        where: {
          name: JobSource.ATS_SMART_RECRUITERS.toString(),
        },
        select: {
          organizationId: true,
        },
      });

      return integrations.map((int) => int.organizationId);
    });

    let totalJobsProcessed = 0;
    let totalJobsUpdated = 0;
    let totalJobsSkipped = 0;

    // For each organization, process all jobs
    for (const organizationId of organizations) {
      const jobs = await step.run(
        `get-jobs-for-org-${organizationId}`,
        async () => {
          return db.job.findMany({
            where: {
              organizationId,
              source: JobSource.ATS_SMART_RECRUITERS,
            },
            include: {
              variables: {
                include: {
                  templateVariable: true,
                },
              },
            },
          });
        },
      );

      totalJobsProcessed += jobs.length;

      // Process each job
      for (const job of jobs) {
        const orgOptInTemplate = await db.orgNotificationTemplate.findFirst({
          where: {
            organizationId,
            triggeredByState: OPT_IN_TRIGGER,
          },
          include: {
            variables: {
              include: {
                templateVariable: true,
              },
            },
          },
        });

        if (orgOptInTemplate) {
          const existingJobOptInTemplate =
            await db.jobNotificationTemplate.findFirst({
              where: {
                jobId: job.id,
                orgTemplateId: orgOptInTemplate.id,
              },
            });
          if (existingJobOptInTemplate) {
            await db.opportunityNotification.deleteMany({
              where: {
                templateId: existingJobOptInTemplate.id,
              },
            });
            await db.jobNotificationTemplate.deleteMany({
              where: {
                id: existingJobOptInTemplate.id,
              },
            });
          }

          const jobNotificationTemplate =
            await createJobNotificationTemplateFromOrgNotificationTemplate(
              job.id,
              orgOptInTemplate,
            );

          const notifications = populateVariablesInNotifications({
            notifications: [jobNotificationTemplate],
            variables: job.variables
              .filter(
                (v) =>
                  v.templateVariable.type ===
                  TemplateVariableType.JOB.toString(),
              )
              .map((v) => ({
                key: v.templateVariable.key,
                value: v.value,
              })),
            replaceFromTemplate: true,
          });

          await Promise.all(
            notifications.map((notification) =>
              db.jobNotificationTemplate.update({
                where: {
                  id: notification.id,
                },
                data: {
                  subject: notification.subject,
                  body: notification.body,
                },
              }),
            ),
          );
        }

        const interviewPlan = job.interviewPlan as IInterviewPlan;

        // Find the index of the inactive stage
        const inactiveStageIndex = interviewPlan.stages.findIndex(
          (stage) => stage.id === stages.INACTIVE,
        );

        if (inactiveStageIndex === -1) {
          totalJobsSkipped++;
          continue;
        }

        // Check if opt-in stage already exists
        const optInStageExists = interviewPlan.stages.some(
          (stage) => stage.id === stages.OPT_IN,
        );

        if (optInStageExists) {
          totalJobsSkipped++;
          continue;
        }

        // Insert opt-in stage after inactive stage
        const updatedStages = [
          ...interviewPlan.stages.slice(0, inactiveStageIndex + 1),
          optInStage,
          ...interviewPlan.stages.slice(inactiveStageIndex + 1),
        ];

        await step.run(`update-job-${job.id}`, async () => {
          await db.job.update({
            where: {
              id: job.id,
            },
            data: {
              interviewPlan: {
                ...interviewPlan,
                initialActiveStageId: stages.OPT_IN,
                stages: updatedStages,
                updatedAt: new Date().toISOString(),
              },
            },
          });
        });

        totalJobsUpdated++;
      }
    }

    return {
      success: true,
      organizationsProcessed: organizations.length,
      totalJobsProcessed,
      totalJobsUpdated,
      totalJobsSkipped,
    };
  },
);

