    const opportunity = await db.opportunity.findUnique({
      where: {
        id: opportunityId,
      },
      select: {
        sequenceInitializedAt: true,
      },
    });

    if (opportunity?.sequenceInitializedAt) {
      return;
    }

    await step.run("create-opportunity-sequence", async () => {
      try {
        await populateSequenceItems(opportunityId);

        return true;
      } catch (error) {
        handleException(error);
        throw error;
      }
    });
  },
);

export const sendOptInEmailFunction = inngest.createFunction(
  {
    id: "send-opt-in-email",
  },
  {
    event: "purplefish/stage.entered",
  },
  async ({ event }) => {
    const { opportunityId, stageId } = event.data;

    if (stageId !== stages.OPT_IN) {
      return;
    }

    await sendNotificationsForTrigger({
      opportunityId,
      trigger: OPT_IN_TRIGGER,
    });
  },
);

export const cancelOpportunitySequenceFunction = inngest.createFunction(
  {
    id: "cancel-opportunity-sequence",
  },
  {
    event: "purplefish/stage.exited",
  },

  async ({ event, step }) => {
    const { opportunityId, stageId } = event.data;

    if (stageId !== stages.PHONE_SCREEN) {
      return;
    }

    await step.run("cancel-sequence-items", async () => {
      await cancelSequenceItems(opportunityId, "Phone Screen stage exited");
    });

    // Clear sequenceInitializedAt to allow re-sequencing
    await step.run("clear-sequence-initialized", async () => {
      await db.opportunity.update({
        where: {
          id: opportunityId,
        },
        data: {
          sequenceInitializedAt: null,
        },
      });
    });
  },
);

export const updateAtsOnStageEnteredFunction = inngest.createFunction(
  {
    id: "update-ats-on-stage-entered",
  },
  {
    event: "purplefish/stage.entered",
  },
  async ({ event, step }) => {
    const { opportunityId, stageId } = event.data;

    // Only process ARCHIVED and COMPLETED stages
    if (stageId !== stages.ARCHIVED && stageId !== stages.COMPLETED) {
      return;
    }

    // Fetch opportunity with related data
    const opportunity = await step.run("fetch-opportunity", async () => {
      return db.opportunity.findUnique({
        where: {
          id: opportunityId,
        },
        include: {
          job: {
            include: {
              organization: true,
            },
          },
        },
      });
    });

    if (!opportunity) {
      return;
    }

    // Check if there's an ATS source for this job
    if (!opportunity.job.source) {
      return;
    }

    // Get the ATS provider from job source
    const provider = getProviderFromJobSource(opportunity.job.source as string);
    if (!provider) {
      return;
    }

    // Only process integrations that support the new pattern
    if (!supportsNewPattern(provider)) {
      return;
    }

    await step.run(
      `update-ats-${opportunity.job.source}-${stageId}`,
      async () => {
        try {
          // Get authenticated integration with decrypted credentials
          const { integration, authToken, config } =
            await getAuthenticatedIntegration(
              opportunity.job.organizationId,
              provider,
            );

          const updateProvider = integration.update;

          // Call appropriate method based on stage
          if (stageId === stages.ARCHIVED) {
            if (!updateProvider?.processArchivedStageEntered) {
              console.log(
                `[${provider}] processArchivedStageEntered not implemented`,
              );
              return;
            }

            const result = await updateProvider.processArchivedStageEntered({
              token: authToken,
              opportunityId,
              config, // Pass config for Kombo integration ID
            });

            if (!result.success) {
              throw new Error(result.message ?? "Update failed");
            }
          } else if (stageId === stages.COMPLETED) {
            if (!updateProvider?.processCompletedStageEntered) {
              console.log(
                `[${provider}] processCompletedStageEntered not implemented`,
              );
              return;
            }

            const result = await updateProvider.processCompletedStageEntered({
              token: authToken,
              opportunityId,
              config, // Pass config for Kombo integration ID
            });

            if (!result.success) {
              throw new Error(result.message ?? "Update failed");
            }
          }
        } catch (error) {
          handleException(error);
          throw error;
        }
      },
    );
  },
);

