import { db } from "@purplefish-ai/db/server";
import { generateObject } from "ai";
import { NonRetriableError } from "inngest";
import { z } from "zod";

import { CeipalJobResponse } from "@/common/libs/ats/ceipal";
import { extractEmails } from "@/common/libs/emails";
import { ceipalInngest } from "@/server/inngest/ceipal-client";
import { aiModel } from "@/server/libs/ai-model";
import { getAtsJobByClientId } from "@/server/libs/ats-jobs";
import { getCeipalJobFromClientId } from "@/server/libs/integrations";
import { createJobFromCeipal } from "@/server/libs/jobs";
import { getMailgunEvent } from "@/server/libs/mailgun";
import { findBestScriptTemplate } from "@/server/libs/script-templates";

import { handleException, MAX_INNGEST_PRIORITY } from "../utils";

const MAX_CEIPAL_FETCH_ATTEMPTS = 1;

export const processMailgunEvent = ceipalInngest.createFunction(
  {
    id: "process-mailgun-event",
    priority: {
      run: MAX_INNGEST_PRIORITY,
    },
  },
  {
    event: "mailgun/webhook.received",
  },
  async ({ event, step, attempt }) => {
    const { mailgunEventId } = event.data;

    const mailgunEvent = await step.run("fetch-mailgun-event", async () => {
      try {
        return await getMailgunEvent(mailgunEventId);
      } catch (error) {
        handleException(error);
        throw error;
      }
    });

    const eventData = await step.run("extract-email-content", async () => {
      const data = mailgunEvent.event as Record<string, unknown>;
      const emailBody = data["body-plain"] as string;
      const htmlBody = data["body-html"] as string;
      const emailSubject = data.subject as string;

      if (!emailBody) {
        throw new NonRetriableError("Missing email body in Mailgun event");
      }

      return {
        emailBody,
        emailSubject: emailSubject || "",
        htmlBody,
        to: data.To as string | undefined,
        cc: data.Cc as string | undefined,
        bcc: data.Bcc as string | undefined,
      };
    });

    const emails = await step.run("extract-emails", async () => {
      const emailFields = [eventData.to, eventData.cc, eventData.bcc];
      return emailFields.flatMap(extractEmails);
    });

    const organization = await step.run("get-organization", async () => {
      const jobsEmails = emails.filter((email) =>
        email.endsWith("@jobs.purplefish.com"),
      );

      if (jobsEmails.length === 0) {
        return null;
      }

      const org = await db.organization.findFirst({
        where: {
          inboundJobsEmail: {
            in: jobsEmails,
          },
        },
      });
      return org;
    });

    if (!organization) {
      return;
    }

    const jobDescriptionFromEmail = `
      Subject: ${eventData.emailSubject}
      Body: ${eventData.emailBody}
    `;

    const emailData = await step.run(
      "extract-job-data-from-email",
      async () => {
        return await generateObject({
          model: aiModel,
          schema: z.object({
            jobTitle: z.string().describe("The job title"),
            clientJobId: z
              .string()
              .nullable()
              .describe(`
              The job client ID if present in the subject, 
              usually a random mix of letters and numbers, sometimes prefixed by a #.
              An example subject might be "BioMerieux # BIO021220243 (New Requirement) - 1 Position(s) $26.40"
              where the clientJobId is "BIO021220243"
            `),
            description: z.string().describe("The full job description"),
            location: z
              .string()
              .nullable()
              .describe("Job location if mentioned"),
            duration: z
              .string()
              .nullable()
              .describe("Contract duration if mentioned"),
            shift: z.string().nullable().describe("Shift timing if mentioned"),
          }),
          prompt: `Extract job details from this email subject and body: ${jobDescriptionFromEmail}. Output as JSON using the attached schema.`,
        });
      },
    );

    const jobCode: string | null = await step.run(
      "fetch-ceipal-data",
      async () => {
        if (attempt === MAX_CEIPAL_FETCH_ATTEMPTS) {
          console.error(
            "Max attempts reached fetching CEIPAL data during processMailgunEvent, continuing with job creation",
          );
          return null;
        }

        if (!emailData.object.clientJobId) {
          return null;
        }

        const atsJob = await getAtsJobByClientId(
          organization.id,
          emailData.object.clientJobId as string,
          emailData.object.jobTitle,
        );
        if (atsJob) {
          return atsJob.key;
        }

        const ceipalData = await getCeipalJobFromClientId({
          organizationId: organization.id,
          ceipalClientJobId: emailData.object.clientJobId as string,
          jobTitle: emailData.object.jobTitle,
        });

        return ceipalData?.JobCode ?? null;
      },
    );

    const bestScriptTemplateId = await step.run(
      "find-best-script-template",
      async () => {
        const scriptTemplate = await findBestScriptTemplate(
          organization.id,
          emailData.object as string,
        );
        return scriptTemplate.id;
      },
    );

    const finalData: CeipalJobResponse = {
      JobCode: jobCode,
      JobTitle: emailData.object.jobTitle,
      JobDescription: jobDescriptionFromEmail,
      ClientJobID: emailData.object.clientJobId as string,
    };

    await step.run("create-job-from-email", async () => {
      try {
        return await createJobFromCeipal({
          organizationId: organization.id,
          ceipalJob: finalData,
          scriptTemplateId: bestScriptTemplateId,
          createdByUserId: null,
          emailSubject: eventData.emailSubject,
          emailBody: eventData.htmlBody,
        });
      } catch (error) {
        handleException(error);
        throw error;
      }
    });
  },
);

