import { CeipalJobResponse } from "@/common/libs/ats/ceipal";
import { extractEmails } from "@/common/libs/emails";
import { ceipalInngest } from "@/server/inngest/ceipal-client";
import { aiModel } from "@/server/libs/ai-model";
